<script setup lang="ts">
import { ref,computed,watch,onBeforeUnmount } from 'vue';
import { useRoute,useRouter } from 'vue-router';
import { Plus,Download,Upload,Search } from 'lucide-vue-next';
import { api,mutate,query,types,text,date,can,useTask,type DTO,type Page } from './shared';
import { download } from '../../shared/api/client';
import {useForm} from './forms';import TaskForm from './TaskForm.vue';
import PageState from './PageState.vue';import Pager from './Pager.vue';
const route=useRoute(),router=useRouter(),mine=computed(()=>route.path==='/my-resources');
const {busy,error,run}=useTask(),{form,open}=useForm();
function restore(row:DTO<'ResourceSummary'>){open({title:'恢复归档资源',fields:[{key:'reason',label:'恢复查阅的原因',type:'textarea',required:true}],onSubmit:async v=>{await mutate(`/resources/${row.id}/actions/unarchive`,{expected_version:row.version,reason:v.reason});await load();}});}
const roles=ref<DTO<'Stage2ResourceRole'>[]>([]);
const tab=ref(String(route.query.tab??'resources')),rows=ref<DTO<'ResourceSummary'>[]>([]),catalog=ref<Record<string,unknown>[]>([]),q=ref(String(route.query.q??'')),type=ref(String(route.query.type_code??'')),role=ref(String(route.query.role??'')),lifecycle=ref(String(route.query.lifecycle??'')),verification=ref(String(route.query.verification??'')),archived=ref(route.query.archived==='true'),page=ref(Number(route.query.page??1)),total=ref(0),more=ref(false);
const tabs=[['resources','资源'],['company','公司主体'],['identity','注册身份'],['platform','平台'],['roles','人员与角色']];
let controller:AbortController|undefined;let timer:ReturnType<typeof setTimeout>;
async function load(){controller?.abort();controller=new AbortController();const signal=controller.signal;await run(async()=>{
 await router.replace({path:route.path,query:Object.fromEntries(Object.entries({tab:tab.value,q:q.value,type_code:type.value,role:role.value,lifecycle:lifecycle.value,verification:verification.value,archived:archived.value?'true':'',page:page.value,person_id:route.query.person_id}).filter(([,v])=>v!==''&&v!==undefined).map(([k,v])=>[k,String(v)]))});
 if(!mine.value&&tab.value==='roles'){const d=await api.get<Page<DTO<'Stage2ResourceRole'>>>('/resource-roles'+query({q:q.value,role:role.value,person_id:route.query.person_id,page:page.value}),signal);roles.value=d.items;total.value=d.pagination.total;more.value=d.pagination.has_next;}else if(mine.value||tab.value==='resources'){
  const data=await api.get<Page<DTO<'ResourceSummary'>>>((mine.value||tab.value==='roles'?'/me/resources':'/resources')+query({q:q.value,type_code:type.value,role:role.value||undefined,lifecycle:lifecycle.value,verification:verification.value,archived:archived.value,page:page.value,page_size:25,sort:'-updated_at,id'}),signal);
  rows.value=data.items;total.value=data.pagination.total;more.value=data.pagination.has_next;
 }else{const endpoint={company:'/companies',identity:'/contact-identities',platform:'/platforms'}[tab.value];const data=await api.get<Page<Record<string,unknown>>>(endpoint+query({q:q.value,page:page.value,page_size:25}),signal);catalog.value=data.items;total.value=data.pagination.total;more.value=data.pagination.has_next;}
 });}
function search(){clearTimeout(timer);timer=setTimeout(()=>{page.value=1;void load();},300);}
watch([()=>route.path,tab,type,role,lifecycle,verification,archived],()=>{page.value=1;void load();});void load();watch(q,search);onBeforeUnmount(()=>{controller?.abort();clearTimeout(timer);});
function change(p:number){page.value=p;void load();}
</script>
<template><header class="page-heading"><div><h1>{{mine?'我的资源':'资源清单'}}</h1><p>{{mine?'仅展示已确认的当前责任与使用关系。':'登记、查找和维护已知资产；关系不完整也可以先建档。'}}</p></div><div v-if="!mine" class="flex flex-wrap gap-2"><button class="btn-secondary" :disabled="busy" @click="run(()=>download('/exports/resources','资源清单.csv'))"><Download class="h-4 w-4"/>导出</button><RouterLink v-if="can('resource.write')" to="/resources/import" class="btn-secondary"><Upload class="h-4 w-4"/>导入</RouterLink><RouterLink v-if="can('resource.write')" :to="{path:'/resources/new',query:tab!=='resources'&&tab!=='roles'?{kind:tab}:{}}" class="btn-primary"><Plus class="h-4 w-4"/>登记</RouterLink></div></header><section class="feishu-section"><div v-if="!mine" class="flex overflow-x-auto border-b border-gray-100" aria-label="清单类型"><button v-for="[value,label] in tabs" :key="value" class="task-tab" :class="tab===value?'task-tab-active':''" @click="tab=value">{{label}}</button></div><div class="toolbar"><div class="relative max-w-sm flex-1"><Search class="absolute left-2.5 top-2.5 h-4 w-4 text-gray-400"/><input v-model="q" class="admin-field !pl-8" aria-label="搜索资源" :placeholder="tab==='identity'?'按辨识名称或脱敏内容搜索':tab==='roles'?'按人员或资源名称搜索':mine||tab==='resources'?'按名称、提供方或用途搜索':'按名称搜索'" maxlength="100"></div><template v-if="mine||tab==='resources'||tab==='roles'"><select v-if="!mine&&tab==='resources'" v-model="type" class="feishu-input max-w-full" aria-label="资源类型"><option value="">所有类型</option><option v-for="(name,key) in types" :key="key" :value="key">{{name}}</option></select><select v-if="mine||tab==='roles'" v-model="role" class="feishu-input" aria-label="我的角色"><option value="">所有角色</option><option v-for="r in ['owner','maintainer','use','controller']" :key="r" :value="r">{{text(r)}}</option></select><select v-if="!mine&&tab==='resources'" v-model="lifecycle" class="feishu-input" aria-label="生命周期"><option value="">所有生命周期</option><option v-for="s in ['unknown','in_use','disabled','retired']" :value="s">{{text(s)}}</option></select><select v-if="!mine&&tab==='resources'" v-model="verification" class="feishu-input" aria-label="核实状态"><option value="">所有核实状态</option><option value="unverified">待核实</option><option value="verified">已核实</option></select><label v-if="!mine&&tab==='resources'" class="flex items-center gap-1 text-xs text-gray-600"><input v-model="archived" type="checkbox">仅归档</label></template></div><p v-if="tab==='roles'&&!mine" class="px-3 py-2 text-xs text-gray-500">同一资源可有不同的负责人、维护人、使用人和控制人。仅展示当前可见且有效的业务关系。</p><PageState :busy="busy" :error="error" :empty="total===0" @retry="load"/><div v-if="total" class="admin-table-scroll"><table class="feishu-table min-w-[600px]"><thead><tr><th>名称</th><th>类型</th><th>{{mine||tab==='roles'?'我的角色':'归属 / 负责人'}}</th><th>状态</th><th>更新</th></tr></thead><tbody v-if="!mine&&tab==='roles'"><tr v-for="r in roles" :key="r.id"><td><RouterLink :to="'/resources/'+r.resource_id" class="text-link font-medium">{{r.resource_name}}</RouterLink></td><td>人员关系</td><td>{{r.person_name}} · {{text(r.role)}}</td><td>{{text(r.confirmation)}}</td><td>{{date(r.valid_from)}}</td></tr></tbody><tbody v-else-if="mine||tab==='resources'"><tr v-for="row in rows" :key="row.id"><td><RouterLink v-if="!archived" :to="'/resources/'+row.id" class="text-link font-medium">{{row.name}}</RouterLink><span v-else class="font-medium">{{row.name}}</span><button v-if="archived&&can('governance.confirm')" class="text-link ml-2" @click="restore(row)">恢复归档</button><p class="mt-1 text-[11px] text-gray-400">{{row.provider_name??row.code}}</p></td><td>{{text(row.type_code)}}</td><td><template v-if="mine||tab==='roles'">{{text((row as DTO<'MyResourceSummary'>).my_roles)}}</template><template v-else>{{row.confirmed_company?.display_name??row.owning_department?.display_name??'待明确'}} / {{row.owner?.display_name??'待指定'}}</template></td><td><span class="feishu-badge bg-gray-100 text-gray-600">{{text(row.lifecycle)}}</span><span class="ml-1 text-[11px] text-gray-500">{{text(row.verification)}}</span></td><td class="whitespace-nowrap text-gray-500">{{date(row.updated_at)}}</td></tr></tbody><tbody v-else><tr v-for="row in catalog" :key="String(row.id)"><td><RouterLink :to="'/directory/'+tab+'/'+row.id" class="text-link font-medium">{{row.name??row.display_name}}</RouterLink></td><td>{{text(row.identity_kind??tab)}}</td><td>{{text(row.masked_value??row.website??row.status)}}</td><td>{{text(row.status)}}</td><td>—</td></tr></tbody></table></div><Pager :page="page" :total="total" :more="more" :busy="busy" @change="change"/></section><TaskForm v-if="form" v-bind="form" @close="form=undefined"/></template>
